// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAccounts List subscription accounts with quota, cooldown and models.
	// (GET /api/accounts)
	ListAccounts(ctx context.Context, request ListAccountsRequestObject) (ListAccountsResponseObject, error)
	// ImportAccount Import an account from an existing OAuth credential.
	// (POST /api/accounts/import)
	ImportAccount(ctx context.Context, request ImportAccountRequestObject) (ImportAccountResponseObject, error)
	// StartAccountLogin Start an OAuth login for a subscription provider.
	// (POST /api/accounts/logins)
	StartAccountLogin(ctx context.Context, request StartAccountLoginRequestObject) (StartAccountLoginResponseObject, error)
	// CancelAccountLogin Cancel a login that has not finished.
	// (DELETE /api/accounts/logins/{state})
	CancelAccountLogin(ctx context.Context, request CancelAccountLoginRequestObject) (CancelAccountLoginResponseObject, error)
	// GetAccountLogin Poll the status of a login.
	// (GET /api/accounts/logins/{state})
	GetAccountLogin(ctx context.Context, request GetAccountLoginRequestObject) (GetAccountLoginResponseObject, error)
	// CompleteAccountLogin Complete a login with the redirect URL the user pasted from the browser.
	// (POST /api/accounts/logins/{state}/complete)
	CompleteAccountLogin(ctx context.Context, request CompleteAccountLoginRequestObject) (CompleteAccountLoginResponseObject, error)
	// GetAccountPool Enabled subscription accounts that dropped out of the pool, per provider.
	// (GET /api/accounts/pool)
	GetAccountPool(ctx context.Context, request GetAccountPoolRequestObject) (GetAccountPoolResponseObject, error)
	// DeleteAccount Delete an account.
	// (DELETE /api/accounts/{id})
	DeleteAccount(ctx context.Context, request DeleteAccountRequestObject) (DeleteAccountResponseObject, error)
	// UpdateAccount Enable or disable an account.
	// (PATCH /api/accounts/{id})
	UpdateAccount(ctx context.Context, request UpdateAccountRequestObject) (UpdateAccountResponseObject, error)
	// ResetAccountCooldown Clear an account's cooldown so it serves requests again.
	// (POST /api/accounts/{id}/reset-cooldown)
	ResetAccountCooldown(ctx context.Context, request ResetAccountCooldownRequestObject) (ResetAccountCooldownResponseObject, error)
	// ListAliases List aliases.
	// (GET /api/aliases)
	ListAliases(ctx context.Context, request ListAliasesRequestObject) (ListAliasesResponseObject, error)
	// CreateAlias Create an alias.
	// (POST /api/aliases)
	CreateAlias(ctx context.Context, request CreateAliasRequestObject) (CreateAliasResponseObject, error)
	// CompileAlias Compile an unsaved alias into its chain of targets; nothing is stored.
	// (POST /api/aliases/compile)
	CompileAlias(ctx context.Context, request CompileAliasRequestObject) (CompileAliasResponseObject, error)
	// DeleteAlias Delete an alias.
	// (DELETE /api/aliases/{name})
	DeleteAlias(ctx context.Context, request DeleteAliasRequestObject) (DeleteAliasResponseObject, error)
	// GetAlias Get an alias.
	// (GET /api/aliases/{name})
	GetAlias(ctx context.Context, request GetAliasRequestObject) (GetAliasResponseObject, error)
	// UpdateAlias Replace an alias.
	// (PUT /api/aliases/{name})
	UpdateAlias(ctx context.Context, request UpdateAliasRequestObject) (UpdateAliasResponseObject, error)
	// GetAliasChain Get the compiled chain of a stored alias, with cooling members marked.
	// (GET /api/aliases/{name}/chain)
	GetAliasChain(ctx context.Context, request GetAliasChainRequestObject) (GetAliasChainResponseObject, error)
	// Login Sign in as the admin and receive a session cookie.
	// (POST /api/auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout End the current session.
	// (POST /api/auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// GetSession Report how the caller is authenticated; 401 when it is not.
	// (GET /api/auth/session)
	GetSession(ctx context.Context, request GetSessionRequestObject) (GetSessionResponseObject, error)
	// ApplyConfig Make the store match a `remora.yaml` document.
	// (POST /api/config/apply)
	ApplyConfig(ctx context.Context, request ApplyConfigRequestObject) (ApplyConfigResponseObject, error)
	// ExportConfig Export the whole configuration as `remora.yaml`, with secrets as `env:NAME` references.
	// (GET /api/config/export)
	ExportConfig(ctx context.Context, request ExportConfigRequestObject) (ExportConfigResponseObject, error)
	// PlanConfig Show the changes a `remora.yaml` document would make; nothing is changed.
	// (POST /api/config/plan)
	PlanConfig(ctx context.Context, request PlanConfigRequestObject) (PlanConfigResponseObject, error)
	// ListCooling List the alias members that are cooling down.
	// (GET /api/cooling)
	ListCooling(ctx context.Context, request ListCoolingRequestObject) (ListCoolingResponseObject, error)
	// GetHealth Report whether remora and its components are healthy.
	// (GET /api/health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// ListKeys List client keys.
	// (GET /api/keys)
	ListKeys(ctx context.Context, request ListKeysRequestObject) (ListKeysResponseObject, error)
	// CreateKey Create a client key. The value is returned only here.
	// (POST /api/keys)
	CreateKey(ctx context.Context, request CreateKeyRequestObject) (CreateKeyResponseObject, error)
	// DeleteKey Delete a client key.
	// (DELETE /api/keys/{id})
	DeleteKey(ctx context.Context, request DeleteKeyRequestObject) (DeleteKeyResponseObject, error)
	// GetKey Get a client key.
	// (GET /api/keys/{id})
	GetKey(ctx context.Context, request GetKeyRequestObject) (GetKeyResponseObject, error)
	// UpdateKey Rename a key, change its allowlist, or enable or disable it.
	// (PATCH /api/keys/{id})
	UpdateKey(ctx context.Context, request UpdateKeyRequestObject) (UpdateKeyResponseObject, error)
	// GetKeyUsage Get the usage of one key over a time range.
	// (GET /api/keys/{id}/usage)
	GetKeyUsage(ctx context.Context, request GetKeyUsageRequestObject) (GetKeyUsageResponseObject, error)
	// ListLogs List request logs, newest first.
	// (GET /api/logs)
	ListLogs(ctx context.Context, request ListLogsRequestObject) (ListLogsResponseObject, error)
	// GetLog Get one log entry with its bodies and fallback path.
	// (GET /api/logs/{id})
	GetLog(ctx context.Context, request GetLogRequestObject) (GetLogResponseObject, error)
	// ListProviders List providers.
	// (GET /api/providers)
	ListProviders(ctx context.Context, request ListProvidersRequestObject) (ListProvidersResponseObject, error)
	// CreateProvider Create a provider.
	// (POST /api/providers)
	CreateProvider(ctx context.Context, request CreateProviderRequestObject) (CreateProviderResponseObject, error)
	// DeleteProvider Delete a provider.
	// (DELETE /api/providers/{name})
	DeleteProvider(ctx context.Context, request DeleteProviderRequestObject) (DeleteProviderResponseObject, error)
	// GetProvider Get a provider.
	// (GET /api/providers/{name})
	GetProvider(ctx context.Context, request GetProviderRequestObject) (GetProviderResponseObject, error)
	// UpdateProvider Replace a provider. Keys sent without a value keep their stored secret.
	// (PUT /api/providers/{name})
	UpdateProvider(ctx context.Context, request UpdateProviderRequestObject) (UpdateProviderResponseObject, error)
	// TestProvider Send a small request to the provider and report the result.
	// (POST /api/providers/{name}/test)
	TestProvider(ctx context.Context, request TestProviderRequestObject) (TestProviderResponseObject, error)
	// ChangePassword Change the admin password.
	// (PUT /api/settings/password)
	ChangePassword(ctx context.Context, request ChangePasswordRequestObject) (ChangePasswordResponseObject, error)
	// ListApiTokens List API tokens.
	// (GET /api/settings/tokens)
	ListApiTokens(ctx context.Context, request ListApiTokensRequestObject) (ListApiTokensResponseObject, error)
	// CreateApiToken Create an API token. The value is returned only here.
	// (POST /api/settings/tokens)
	CreateApiToken(ctx context.Context, request CreateApiTokenRequestObject) (CreateApiTokenResponseObject, error)
	// DeleteApiToken Delete an API token.
	// (DELETE /api/settings/tokens/{id})
	DeleteApiToken(ctx context.Context, request DeleteApiTokenRequestObject) (DeleteApiTokenResponseObject, error)
	// GetStats Get volume, errors, latency, tokens and cost over a time range.
	// (GET /api/stats)
	GetStats(ctx context.Context, request GetStatsRequestObject) (GetStatsResponseObject, error)
	// GetVersion Report the version of remora and of each engine it runs.
	// (GET /api/system/version)
	GetVersion(ctx context.Context, request GetVersionRequestObject) (GetVersionResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

